public class UserNotificationService {
    private final EmailService emailService;

    // Anti-pattern: isPresent-then-get
    public void notifyUserOld(Long userId) {
        Optional<User> userOpt = repository.findById(userId);
        if (userOpt.isPresent()) {
            User user = userOpt.get();
            emailService.sendWelcome(user.getEmail());
        }
    }

    // Better: using ifPresent
    public void notifyUser(Long userId) {
        repository.findById(userId)
            .ifPresent(user -> emailService.sendWelcome(user.getEmail()));
    }

    // Java 9+: ifPresentOrElse for both branches
    public void notifyOrLog(Long userId) {
        repository.findById(userId)
            .ifPresentOrElse(
                user -> emailService.sendWelcome(user.getEmail()),
                () -> log.warn("User not found: {}", userId)
            );
    }
}

