import java.util.Optional;

public class OrElseEagerDemo {
    static String buildDefault() {
        System.out.println("building fallback");
        return "Guest";
    }

    public static void main(String[] args) {
        String name = Optional.of("Alice").orElse(buildDefault());
        System.out.println(name);
    }
}
```
`building fallback` is printed even though the returned name is `Alice`, because the argument is evaluated before `orElse` is called.

