import java.util.Optional;

record Address(String street, String city, String postalCode) {}

record User(long id, String name, Address address) {
    Optional<Address> addressOptional() {
        return Optional.ofNullable(address);
    }
}

interface UserRepository {
    Optional<User> findById(long id);
}

class UserService {
    private final UserRepository repository;

    UserService(UserRepository repository) { this.repository = repository; }

    Optional<String> cityWithMap(long userId) {
        return repository.findById(userId)
            .map(User::address)
            .map(Address::city);
    }

    Optional<String> cityWithFlatMap(long userId) {
        return repository.findById(userId)
            .flatMap(User::addressOptional)
            .map(Address::city);
    }
}
```

