public class Order {
    private Coupon coupon;                       // may be null internally
    public Optional<Coupon> getCoupon() {       // Optional on the way out
        return Optional.ofNullable(coupon);
    }
    public void apply(Coupon c) { this.coupon = c; }
    public void apply()          { this.coupon = null; }
}
